#!/usr/bin/env node
'use strict';
const fs = require('fs');
const path = require('path');
const yaml = require('js-yaml');

const ROOT = path.resolve(__dirname, '../..');
const OUT = path.join(ROOT, '.cursor/rules');

const spec = yaml.load(fs.readFileSync(path.join(ROOT, '.kit/conventions/typescript.yaml'), 'utf8'));
const titleSpec = yaml.load(fs.readFileSync(path.join(ROOT, '.kit/conventions/pr-title.yaml'), 'utf8'));

fs.mkdirSync(OUT, { recursive: true });

const BANNER =
  '<!-- GENERATED by .kit/bin/generate.cjs — do not edit.\n' +
  '     Edit .kit/conventions/*.yaml and rerun `pnpm kit:generate`. -->';

function write(name, frontmatter, body) {
  const fm = Object.entries(frontmatter)
    .map(([k, v]) => `${k}: ${Array.isArray(v) ? v.join(', ') : v}`)
    .join('\n');
  fs.writeFileSync(path.join(OUT, name), `---\n${fm}\n---\n\n${BANNER}\n\n${body}\n`);
  console.log(`  wrote .cursor/rules/${name}`);
}

// Clear previously generated files so a removed rule actually disappears.
// Only touches files carrying the banner — hand-written rules are left alone.
for (const f of fs.readdirSync(OUT)) {
  if (!f.endsWith('.mdc')) continue;
  const p = path.join(OUT, f);
  if (fs.readFileSync(p, 'utf8').includes('GENERATED by .kit/bin/generate.cjs')) {
    fs.unlinkSync(p);
  }
}

// ── 00: boundaries, always on ────────────────────────────────────────────────
// The only always-apply file. Kept short deliberately: it costs context on
// every single turn, so it carries refusals and nothing else.
const boundaries = (spec.restricted || [])
  .map((r) => {
    const what = r.path || r.concern || (r.nodes && r.nodes.join(', ')) || r.action;
    return `- **${what}** — ${r.reason}${r.redirect ? ` See ${r.redirect}` : ''}`;
  })
  .join('\n');

write(
  '00-boundaries.mdc',
  {
    description: 'Ownership boundaries — areas the n8n team owns; do not scaffold into these',
    alwaysApply: true,
  },
  [
    '# Restricted areas',
    '',
    'Do not generate or modify code in these areas. Stop, tell the user which',
    'boundary applies and why, and name the escalation path. Do not offer a',
    'workaround.',
    '',
    boundaries,
    '',
    `Source: \`.kit/conventions/typescript.yaml\` \`restricted:\``,
  ].join('\n'),
);

// ── glob-scoped rule files ───────────────────────────────────────────────────
// Grouped by scope signature so nodes-base rules never load during cli work.
// This is what an always-on AGENTS.md structurally cannot do.
const groups = new Map();
for (const r of spec.rules || []) {
  if (!r.scope || r.severity === 'advisory') continue;
  const key = r.scope.join('|');
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(r);
}

const labelFor = (globs) => {
  const g = globs[0];
  if (g.includes('nodes-base')) return 'nodes-base';
  if (g.includes('packages/cli') || g.includes('@n8n/db')) return 'backend';
  if (g.includes('frontend')) return 'frontend';
  if (g.includes('workflows')) return 'workflows';
  return g.replace(/[^a-z0-9]+/gi, '-').replace(/^-|-$/g, '').slice(0, 40);
};

let n = 10;
for (const [key, rules] of groups) {
  const globs = key.split('|');
  const body = rules
    .map((r) => {
      const out = [`## ${r.id} — ${r.statement}`, '', `Severity: **${r.severity}**  ·  Source: \`${r.source}\``];
      if (r.fix_hint) out.push('', `Fix: \`${r.fix_hint}\``);
      if (r.note) out.push('', `> ${r.note.trim().replace(/\n\s*/g, ' ')}`);
      return out.join('\n');
    })
    .join('\n\n');

  write(
    `${n}-${labelFor(globs)}.mdc`,
    {
      description: `n8n conventions for ${globs.join(', ')}`,
      globs,
      alwaysApply: false,
    },
    [
      `# Conventions — ${labelFor(globs)}`,
      '',
      'These are enforced by `pnpm kit:precheck` locally and by the',
      '`Kit: convention checks` workflow in CI. Follow them when writing or',
      'editing code in scope; violations block the PR.',
      '',
      body,
    ].join('\n'),
  );
  n += 10;
}

// ── advisory rules: agent-surfaced, never gated ──────────────────────────────
const advisory = (spec.rules || []).filter((r) => r.severity === 'advisory');
if (advisory.length) {
  write(
    '80-advisory.mdc',
    {
      description:
        'Conventions with no reliable static check — raise these in review of n8n code, they are not enforced by CI',
      alwaysApply: false,
    },
    [
      '# Advisory conventions',
      '',
      'Stated by n8n but not statically checkable. Nothing gates on these, so',
      'raise them when relevant rather than assuming CI will catch them.',
      '',
      advisory
        .map((r) => {
          const out = [`## ${r.id} — ${r.statement}`];
          if (r.source) out.push('', `Source: \`${r.source}\``);
          if (r.note) out.push('', `> ${r.note.trim().replace(/\n\s*/g, ' ')}`);
          return out.join('\n');
        })
        .join('\n\n'),
    ].join('\n'),
  );
}

// ── 90: PR title, agent-requested ────────────────────────────────────────────
write(
  '90-pr-title.mdc',
  {
    description:
      'PR title convention — use when writing or reviewing a PR title, commit subject, or changelog entry',
    alwaysApply: false,
  },
  [
    '# PR title convention',
    '',
    'Format: `type(scope): Subject`',
    '',
    `**Types:** ${titleSpec.vocabulary.types.join(', ')}`,
    '',
    `**Scopes:** ${titleSpec.vocabulary.scopes.join(', ')}, or \`<Node display name> Node\``,
    '',
    `Multiple scopes are separated by \`${titleSpec.vocabulary.multi_scope.separator}\` (comma + space).`,
    '',
    '**Subject:** uppercase initial, no trailing period, present tense, no Linear',
    'ticket number, no PR number. `(no-changelog)` must be the final element.',
    '',
    '## Known traps',
    '',
    `- \`revert\` is **not** a valid type, despite being documented in \`.github/pull_request_title_conventions.md\` and in \`.agents/skills/create-pr/SKILL.md\`. CI rejects it.`,
    `- The present-tense check fires when the first word ends in "ed", so \`Embed\`, \`Speed\`, \`Seed\`, \`Feed\` and \`Exceed\` are rejected even though they are correct imperatives.`,
    `- Scope \`ai-builder\` is valid upstream but absent from both in-repo documented lists.`,
    '',
    `Authority: \`${titleSpec.authority.repo}@${titleSpec.authority.ref}\`, vendored at`,
    `\`${titleSpec.authority.vendored_at}\`. Run \`pnpm kit:drift\` to check the`,
    'in-repo documentation against it.',
  ].join('\n'),
);

console.log('\nGenerated from .kit/conventions/. Rerun after any spec change.\n');
